class Solution {
  public int[] sumAndMultiply(String s, int[][] queries) {
    final long MOD = 1_000_000_007L;
    int m = s.length();
    long[] value = new long[m + 1]; // concatenation of non-zero digits in s[0..i)
    long[] digitSum = new long[m + 1];
    int[] count = new int[m + 1];
    long[] pow10 = new long[m + 1];
    pow10[0] = 1;
    for (int i = 0; i < m; i++) {
      int d = s.charAt(i) - '0';
      pow10[i + 1] = pow10[i] * 10 % MOD;
      value[i + 1] = d != 0 ? (value[i] * 10 + d) % MOD : value[i];
      digitSum[i + 1] = digitSum[i] + d;
      count[i + 1] = count[i] + (d != 0 ? 1 : 0);
    }
    int[] ans = new int[queries.length];
    for (int q = 0; q < queries.length; q++) {
      int l = queries[q][0], r = queries[q][1] + 1;
      int digits = count[r] - count[l];
      long x = ((value[r] - value[l] * pow10[digits]) % MOD + MOD) % MOD;
      ans[q] = (int) (x * (digitSum[r] - digitSum[l]) % MOD);
    }
    return ans;
  }
}
